package weibo

import (
	"encoding/json"
	"os"
	"testing"

	"github.com/Brilliant666/DokiTool-Go/backend/internal/unified"
)

// Expected values are generated by the frozen PHP 8.3.6 production formatter.
// The Go code only consumes the immutable oracle and never writes expected.
func TestPHPWeiboFullFormatter(t *testing.T) {
	bytes, err := os.ReadFile("testdata/php-formatter-baseline.json")
	if err != nil {
		t.Fatal(err)
	}
	fixture, err := unified.Decode(bytes)
	if err != nil {
		t.Fatal(err)
	}
	if fixture["php_source_commit"] != "25beaee107f8c1a208ced9deb3c637068445e316" || !unified.Equal(fixture["schema"], 1) {
		t.Fatal("unexpected PHP formatter provenance")
	}
	var raw struct {
		Cases []struct {
			Input json.RawMessage
		}
	}
	if err := json.Unmarshal(bytes, &raw); err != nil {
		t.Fatal(err)
	}
	cases := unified.Slice(fixture["cases"])
	if len(cases) != 29 || len(raw.Cases) != 29 {
		t.Fatalf("incomplete full PHP formatter oracle: got %d cases", len(cases))
	}
	counts := map[string]int{}
	for index, item := range cases {
		entry := unified.Map(item)
		t.Run(unified.Str(entry["id"]), func(t *testing.T) {
			input := unified.Map(entry["input"])
			operation := unified.Str(entry["operation"])
			counts[operation]++
			var got unified.Object
			switch operation {
			case "status":
				got = legacyWeiboFormatStatus(unified.Map(input["status"]))
			case "component":
				var rawInput struct {
					Component json.RawMessage
				}
				if err := json.Unmarshal(raw.Cases[index].Input, &rawInput); err != nil {
					t.Fatal(err)
				}
				keys, err := weiboURLKeysFromRaw(rawInput.Component, "data", "Component_Play_Playinfo", "urls")
				if err != nil {
					t.Fatal(err)
				}
				got = legacyWeiboFormatComponent(unified.Map(input["component"]), unified.Map(input["status"]), keys)
			default:
				t.Fatalf("unexpected formatter operation %q", operation)
			}
			if !unified.Equal(got, entry["expected"]) {
				t.Fatalf("frozen PHP formatter mismatch:\nGo  %#v\nPHP %#v", got, entry["expected"])
			}
		})
	}
	if counts["status"] != 18 || counts["component"] != 11 {
		t.Fatalf("incorrect formatter kind inventory: %#v", counts)
	}
}

func TestWeiboStatusLoginEnvelope(t *testing.T) {
	for _, tc := range []struct{ body, want string }{
		{`{"ok":-100,"url":"https://weibo.com/login.php?return=fixture"}`, "UPSTREAM_BLOCKED"},
		{`{"ok":-100,"url":"https://example.org/login.php"}`, "UPSTREAM_INVALID_RESPONSE"},
		{`{"ok":-100,"url":"https://weibo.com/elsewhere"}`, "UPSTREAM_INVALID_RESPONSE"},
		{`{"ok":1,"url":"https://weibo.com/login.php"}`, "UPSTREAM_INVALID_RESPONSE"},
	} {
		status, err := unified.Decode([]byte(tc.body))
		if err != nil {
			t.Fatal(err)
		}
		got := adaptLegacy(legacyWeiboFormatStatus(status), "https://weibo.com/123/Test", 1730000000)
		if got["code"] != tc.want {
			t.Errorf("%s: got %v, want %s", tc.body, got["code"], tc.want)
		}
	}
}
